<script setup>
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRouter} from 'vue-router'
import {api} from '../api'
import {retrievalModes} from '../retrieval'
import {labelOf} from '../ui'
import RetrievalDetails from './RetrievalDetails.vue'
const emit=defineEmits(['dirty']),router=useRouter(),step=ref(1),templates=ref([]),kbs=ref([]),busy=ref(false),error=ref(''),inspection=ref(null),inspectionSeconds=ref(0)
let submitted=false,inspectionTimer=null
const form=ref({title:'',template_id:'',knowledge_base_id:'',requirements:'',generation_mode:'strict',period_start:'',period_end:'',field_values:{},allow_missing:false,workflow_version:1,preflight_id:'',mode:null})
const selected=computed(()=>templates.value.find(t=>t.id===Number(form.value.template_id)))
const eligible=computed(()=>kbs.value.filter(k=>!selected.value?.knowledge_base_ids?.length||selected.value.knowledge_base_ids.includes(k.id)))
const fields=ref([]),fieldsReady=ref(false)
watch(form,value=>{if(!submitted)emit('dirty',!!(value.title||value.requirements||value.period_start||value.period_end||Object.values(value.field_values).some(Boolean)))},{deep:true})
onUnmounted(()=>{clearInterval(inspectionTimer);emit('dirty',false)})
onMounted(async()=>{try{[templates.value,kbs.value]=await Promise.all([api('/api/templates'),api('/api/knowledge-bases')]);templates.value=templates.value.filter(t=>t.lifecycle==='published');const requested=Number(router.currentRoute.value.query.template);if(requested&&templates.value.some(t=>t.id===requested))form.value.template_id=requested}catch(e){error.value=e.message}})
watch(()=>form.value.template_id,async value=>{fieldsReady.value=false;inspection.value=null;form.value.knowledge_base_id='';form.value.field_values={};fields.value=[];if(!value)return;try{const t=await api(`/api/report-templates/${value}`);if(Number(value)!==Number(form.value.template_id))return;fieldsReady.value=true;fields.value=t.field_mappings.filter(m=>m.target==='user_input');if(eligible.value.length===1)form.value.knowledge_base_id=eligible.value[0].id}catch(e){error.value=e.message}})
const valid=computed(()=>fieldsReady.value&&form.value.title.trim()&&selected.value&&eligible.value.some(k=>k.id===Number(form.value.knowledge_base_id))&&fields.value.every(f=>!f.required||form.value.field_values[f.key]?.trim())&&(!form.value.period_start||!form.value.period_end||form.value.period_start<=form.value.period_end))
async function inspect(){error.value='';busy.value=true;inspectionSeconds.value=0;inspectionTimer=setInterval(()=>inspectionSeconds.value++,1000);try{inspection.value=await api('/api/reports/preflight',{method:'POST',body:JSON.stringify(form.value)});form.value.preflight_id=inspection.value.preflight_id;step.value=3}catch(e){error.value=e.message}finally{clearInterval(inspectionTimer);inspectionTimer=null;busy.value=false}}
function chapterLabel(section){const title=(section.title||'').trim();return /^\d+(?:[.．、]|\s)/.test(title)?title:`${section.ordinal+1}. ${title}`}
async function generate(){busy.value=true;error.value='';try{const row=await api('/api/report-tasks',{method:'POST',body:JSON.stringify(form.value)});submitted=true;emit('dirty',false);router.push(`/reports/${row.id}`)}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><section class="author-page"><div class="author-header"><div><h2>新建报告</h2><p>先明确需求和资料，再检查大纲与证据。生成后可继续修改，不会直接成为正式稿。</p></div><button class="secondary-button" @click="router.push('/reports')">返回我的报告</button></div>
 <ol class="wizard-steps"><li v-for="(label,i) in ['报告需求','模板与资料','大纲与证据检查']" :key="label" :class="{current:step===i+1,done:step>i+1}">{{i+1}}. {{label}}</li></ol>
 <fieldset v-if="step===1" class="card author-form generation-mode-picker"><legend>报告生成模式</legend><label class="check-line"><input v-model="form.generation_mode" type="radio" value="strict" name="generation-mode"/>严格事实证据</label><p class="muted">检索后逐句核验，仅保留证据支持的句段。适合事实汇总、审计说明和需要严格溯源的报告。</p><label class="check-line"><input v-model="form.generation_mode" type="radio" value="synthesis" name="generation-mode"/>基于证据综合生成</label><p class="muted">从RAG读取资料后交给Kimi撰写连贯正文，允许归纳、分析、实验方案与建议。关键事实保留引用，推断与建议明确区分；不执行逐句核验，需人工审阅。未提供的实验结果写为待实测。</p></fieldset>
 <p v-if="step!==1" class="muted">生成模式：{{form.generation_mode==='synthesis'?'基于证据综合生成（未逐句核验，需人工审阅）':'严格事实证据（逐句核验）'}}。更改模式请返回第一步并重新检查证据。</p>
 <div v-if="error" class="error-banner" role="alert">{{error}}</div>
 <form v-if="step===1" class="card author-form" @submit.prevent="step=2"><h3>这份报告要解决什么问题？</h3><label class="field">报告名称<input v-model="form.title" class="input" maxlength="100" required placeholder="例如：知识库项目第一周技术方案"/></label><label class="field">用途和写作要求<textarea v-model="form.requirements" class="textarea" maxlength="5000" placeholder="说明读者、重点、范围与希望回答的问题；不需要填写技术提示词。"/></label><div class="form-grid"><label class="field">业务开始日期（可选）<input v-model="form.period_start" class="input" type="date" :max="form.period_end||undefined"/></label><label class="field">业务结束日期（可选）<input v-model="form.period_end" class="input" type="date" :min="form.period_start||undefined"/></label></div><p class="muted">日期表示报告关注的业务期间，不是文件上传时间。没有日期依据的事实仍需补充资料。</p><div class="author-actions"><button class="primary-button" :disabled="!form.title.trim()">下一步：选择模板与资料</button></div></form>
 <form v-if="step===2" class="card author-form" @submit.prevent="inspect"><h3>选择已发布模板与授权知识库</h3><label class="field">报告模板<select v-model.number="form.template_id" class="select" required><option disabled value="">请选择模板及版本</option><option v-for="t in templates" :key="t.id" :value="t.id">{{t.name||'历史未命名模板'}} · {{t.version}}</option></select></label><p v-if="selected" class="muted">{{selected.blueprint?.purpose||selected.description||'此模板未填写用途说明'}} · {{selected.sections.length}}节</p><label class="field">资料知识库<select v-model.number="form.knowledge_base_id" class="select" required :disabled="!selected"><option disabled value="">请选择适用知识库</option><option v-for="kb in eligible" :key="kb.id" :value="kb.id">{{kb.name}} · {{kb.document_count}}个文档</option></select></label><p v-if="selected&&!eligible.length" class="error-banner">没有适用且有权限的知识库，请更换模板或联系管理员授权。</p><label class="field">检索模式
   <select v-model="form.mode" class="select" :disabled="busy">
    <option :value="null">使用系统默认</option>
    <option v-for="item in retrievalModes" :key="item.value" :value="item.value">{{item.label}}</option>
   </select>
  </label><h4 v-if="fields.length">本模板需要填写的业务信息</h4><label v-for="field in fields" :key="field.key" class="field">{{field.key}}{{field.required?' *':'（可选）'}}<input v-model="form.field_values[field.key]" class="input" :required="field.required" :type="field.input_type==='date'?'date':field.input_type==='number'?'number':'text'" maxlength="4000"/></label><p v-if="busy" class="muted" role="status">正在逐章检查 {{selected?.sections.length||0}} 节的证据，已等待 {{inspectionSeconds}} 秒。此步骤可能需要几十秒，请勿重复提交。</p><div class="author-actions"><button type="button" class="secondary-button" :disabled="busy" @click="step=1">上一步</button><button class="primary-button" :disabled="busy||!valid">{{busy?'正在检查证据…':'检查大纲与证据'}}</button></div></form>
 <section v-if="step===3&&inspection" class="card author-form"><h3>生成前确认</h3><p><strong>{{form.title}}</strong> · {{selected.name}} {{selected.version}} · {{eligible.find(k=>k.id===form.knowledge_base_id)?.name}} · {{labelOf(inspection.mode)}}</p><div v-for="s in inspection.sections" :key="s.ordinal" class="preflight-row"><div><strong>{{chapterLabel(s)}}</strong><small>{{s.kind==='container'?'目录容器':s.kind==='fixed'?'模板固定内容':s.kind==='analysis'?'有依据的分析':s.kind==='recommendation'?'有依据的建议':'事实正文'}}</small></div><span class="badge" :class="s.ready?'green':'amber'">{{['fixed','container'].includes(s.kind)?'人工核对结构':s.ready?`${s.evidence_count}条候选证据`:'待补充资料'}}</span><RetrievalDetails :pipeline="s.retrieval"/><details v-if="s.evidence.length"><summary>检查来源</summary><article v-for="e in s.evidence" :key="e.chunk_id"><router-link :to="`/documents/${e.document_id}?chunk=${e.chunk_id}`" target="_blank">{{e.source}}</router-link><p>{{e.text}}</p></article></details></div><p v-for="warning in inspection.warnings" :key="warning" class="muted">{{warning}}</p><label v-if="inspection.missing" class="check-line"><input v-model="form.allow_missing" type="checkbox"/>我知道有{{inspection.missing}}个必需章节证据不足，先生成带“待补充”标记的草稿</label><p class="muted">{{form.generation_mode==='synthesis'?'将检索资料交给Kimi综合撰写，关键事实保留引用，分析与建议明确区分。生成结果未经逐句核验，请人工审阅。':'候选证据不等于事实已获支持。生成时逐句独立核验，未经支持的陈述不会进入生成正文。'}}</p><div class="author-actions"><button class="secondary-button" :disabled="busy" @click="step=2;inspection=null">返回修改</button><button class="primary-button" :disabled="busy||!!inspection.missing&&!form.allow_missing" @click="generate">{{busy?'提交中…':'生成报告草稿'}}</button></div></section>
</section></template>
<style scoped>
.preflight-row{align-items:flex-start}.preflight-row>.badge{align-self:flex-start;white-space:nowrap}.preflight-row>.retrieval-details{flex-basis:100%;min-width:0;margin:0}
.generation-mode-picker{margin-bottom:20px;min-width:0}.generation-mode-picker legend{font-weight:600;padding:0 8px}.generation-mode-picker input[type=radio]{width:auto}
</style>
